  const id=draft.id,controller=new AbortController();uploadController.current=controller;setUploading(true);setUploadTaskId(id);setUploadKind(kind);setError('');
  const previews=files.filter(file=>/^image\/(png|jpeg|webp|gif|avif)$/.test(file.type)).map(file=>({name:file.name,url:URL.createObjectURL(file)})),used=new Set<string>();setUploadPreviews(previews);setCardEditor(null);requestAnimationFrame(()=>document.querySelector('.upload-local-preview')?.scrollIntoView({block:'nearest'}));
