   if(driveConfig.enabled){
    const result=await uploadCentralBatch(files,{taskId:id,kind,signal:controller.signal,onProgress:setUploadProgress,onAttachment:(attachment,board)=>{const preview=previews.find(p=>p.name===attachment.name&&!used.has(p.url));acceptUpload(attachment,board,id,preview?.url);if(preview){used.add(preview.url);setUploadPreviews(all=>all.filter(p=>p.url!==preview.url))}}});
    setNotice(result.uploaded+' arquivo(s) confirmado(s) no Drive e no cartão.');if(result.errors.length)setError(result.errors.join(' '));return;
   }
   const result=await uploadArtworkBatch(files,{kind,signal:controller.signal,onProgress:setUploadProgress,onAttachment:attachment=>setDraft(d=>{if(!d||d.id!==id)return d;const attachments=[...d.attachments,attachment];return {...d,attachments,coverUrl:automaticCover(attachments)}})});
   setNotice(result.uploaded+' arquivo(s) enviado(s). Feche o cartão para salvar.');if(result.failedBackups)setError('Há anexos com backup pendente. Confira antes de reenviar.');
